import{_ as e,c as o,o as t,b0 as r}from"./chunks/framework.Becqh7-x.js";const l="/linux-dev-docs/assets/image-20260114115035142.0N5J_1Ec.png",s="/linux-dev-docs/assets/image-20260114114749362.Qn-HUfEW.png",f=JSON.parse('{"title":"LV005-内存映射简介","description":null,"frontmatter":{"title":"LV005-内存映射简介","date":"2026-01-14T11:41:03.000Z","icon":"famicons:logo-markdown","permalink":"/sdoc/bare/boot/126d2ce7a63708a85e16b3dd","index":true,"tags":null,"categories":null,"copyright":false,"keywords":null,"cover":null,"comments":null,"mathjax":null,"top":null,"description":null,"tdoc":{"detailDate":"2026-01-14T11:41:03.138Z","fulluuid":"85e16b3ddf57441c970f318e6d7fc8cc","useduuid":"85e16b3dd"}},"headers":[],"relativePath":"sdoc/bare/boot/126d2ce7a63708a85e16b3dd.md","filePath":"sdoc/25-裸机开发/05-imx6ull启动/LV005-内存映射简介.md","lastUpdated":1768604092000}'),n={name:"sdoc/bare/boot/126d2ce7a63708a85e16b3dd.md"};function d(m,a,p,i,c,_){return t(),o("div",null,[...a[0]||(a[0]=[r('<h1 id="lv005-内存映射简介" tabindex="-1">LV005-内存映射简介 <a class="header-anchor" href="#lv005-内存映射简介" aria-label="Permalink to &quot;LV005-内存映射简介&quot;">​</a></h1><p>这一部分主要看《i.MX 6ULL Applications Processor Reference Manual 》的Chapter 2 Memory Maps 。</p><h2 id="一、arm-platform-memory-map" tabindex="-1">一、ARM Platform Memory Map <a class="header-anchor" href="#一、arm-platform-memory-map" aria-label="Permalink to &quot;一、ARM Platform Memory Map&quot;">​</a></h2><p>i.MX6UL外设寄存器以及内存被映射到4G的地址空间</p><p><img src="'+l+'" alt="image-20260114115035142"></p><p>这里我们只关关心内存映射，结合上图说明如下：</p><p>标号①，DDR映射区域。DDR作为i.MX6UL的主内存区域，它被映射在0x8000 0000地址处，最大空间为2G， 实际可用大小与选择的DDR芯片容量有关。</p><p>标号②，QSPI1映射区域，i.MX6UL可以外接串行norflash，norflahs映射到0x6000 000起始地址处。 norflash，支持“本地执行”作用类似于STM32的内部FLASH。NXP的跨界处理器RT1050系列 就是用这个外部norflah存储代码。因为开发板已经使用了容量更大的EMMC或nand flash作为主存储器， 所以配套开发板并没有外接norFlash</p><p>标号③，EIM外扩存储器映射区域。i.MX6UL可以通过EIM总线外扩存储器，我们这里没有用到，不做过多介绍。</p><p>标号④，启动引导程序（Boot ROM）内存映射区域，它位于芯片内部。启动引导程序（Boot ROM）位于起始 地址0x0000 0000 处。我们知道芯片上电后（或硬件复位）会自动从“0”地址处开始执行。和容易得出，这里 就是保存的启动引导代码。有关启动引导程序（Boot ROM）是如何工作的，我们将在下一小节详细介绍。</p><p>从上图我们可以知道i.MX6UL支持将多种存储器映射到4G的地址空间，我们只使用了DDR作为i.MX6UL的主内 存区域，起始地址为0x8000 0000 ，大小由实际使用的DDR芯片决定。启动引导程序（Boot ROM）位于“0”地址处，大小为96Kb。</p><h2 id="二、dma-memory-map" tabindex="-1">二、DMA memory map <a class="header-anchor" href="#二、dma-memory-map" aria-label="Permalink to &quot;二、DMA memory map&quot;">​</a></h2><p>这个没仔细研究，后面再学习吧。</p><p><img src="'+s+'" alt="image-20260114114749362"></p>',14)])])}const M=e(n,[["render",d]]);export{f as __pageData,M as default};
